import { computed, ref } from 'vue'
import { watchDebounced } from '@vueuse/core'
import { useTableState } from './useTableState'
import { DEFAULT_DAT_FORMAT } from '@/constants'
import { generateId, normalize, buildResponseMatchKey, buildUniqueLithoLookup } from '@/utils/helpers'
import { loadExcelExportDeps, loadPdfExportDeps } from '@/utils/exportLoaders'
import {
  createIdentifierRow,
  buildIdentifierObservation,
  parseIdentifierLine,
} from '@/utils/parsers'
import { apiFetch } from '@/utils/apiFetch'

export { createIdentifierRow, buildIdentifierObservation }

function summarizeObservations(rows) {
  const summary = new Map()
  const add = (label) => summary.set(label, (summary.get(label) || 0) + 1)

  rows.forEach((row) => {
    const issues = String(row.observaciones || '')
      .split(' · ')
      .map(issue => issue.trim())
      .filter(Boolean)

    const hasMissingTipo = issues.includes('Tipo sin marcar')
    const hasMissingDni = issues.includes('DNI sin marcar')
    const hasMissingAula = issues.includes('Aula sin marcar')

    if (hasMissingTipo && hasMissingDni && hasMissingAula) {
      add('Sin identificación completa')
      return
    }

    issues.forEach((issue) => {
      if (/^DNI incompleto \(/.test(issue)) {
        add('DNI incompleto')
        return
      }
      if (/^Aula incompleta \(/.test(issue)) {
        add('Aula incompleta')
        return
      }
      add(issue)
    })
  })

  const priority = [
    'Sin identificación completa',
    'DNI sin marcar',
    'DNI incompleto',
    'Tipo sin marcar',
    'Aula sin marcar',
    'Aula incompleta',
  ]

  return Array.from(summary.entries())
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => {
      const left = priority.indexOf(a.label)
      const right = priority.indexOf(b.label)
      if (left !== -1 || right !== -1) {
        return (left === -1 ? priority.length : left) - (right === -1 ? priority.length : right)
      }
      return b.count - a.count || a.label.localeCompare(b.label)
    })
}

/**
 * Composable para gestión de identificadores
 */
export function useIdentifiers(formatConfig) {
  const effectiveFormatConfig = () => formatConfig?.value || DEFAULT_DAT_FORMAT
  const tableState = useTableState({
    pageSize: 10,
    createRow: createIdentifierRow,
    filterFn: (row, searchValue) => {
      const needle = normalize(searchValue)
      return (
        normalize(row.dni).includes(needle) ||
        normalize(row.lectura).includes(needle) ||
        normalize(row.litho).includes(needle) ||
        normalize(row.tipo).includes(needle) ||
        normalize(row.observaciones).includes(needle)
      )
    },
  })

  // Sources (archivos importados)
  const sources = ref([])
  const apiLoading = ref(false)
  const apiSyncing = ref(false)
  const apiReady = ref(false)
  let skipNextApiSync = false

  // Computed
  const identifierHasData = computed(() => tableState.rows.value.length > 0)

  const observations = computed(() =>
    tableState.rows.value.filter(
      (row) => row.observaciones && row.observaciones !== 'Sin observaciones'
    )
  )

  const observationCount = computed(() => observations.value.length)
  const observationSummary = computed(() => summarizeObservations(observations.value))
  const observationByRowId = computed(() => {
    const map = new Map()
    observations.value.forEach(row => map.set(row.id, row))
    return map
  })
  // Lookup por clave de match
  const identifierLookup = computed(() => {
    const map = new Map()
    tableState.rows.value.forEach((row) => {
      const key = buildResponseMatchKey(row)
      map.set(key, row)
    })
    return map
  })

  // Lookup por litho
  const identifierLookupByLitho = computed(() => {
    return buildUniqueLithoLookup(tableState.rows.value)
  })

  async function initializeIdentifiers() {
    apiLoading.value = true
    try {
      const [rowsRes, sourcesRes] = await Promise.all([
        apiFetch('/identificadores/'),
        apiFetch('/identifier-sources/'),
      ])
      if (!rowsRes.ok || !sourcesRes.ok) throw new Error('No se pudieron cargar los identificadores.')

      const [rowsData, sourcesData] = await Promise.all([
        rowsRes.json(),
        sourcesRes.json(),
      ])

      apiReady.value = true
      if (rowsData.length > 0 || sourcesData.length > 0) {
        skipNextApiSync = true
        tableState.setRows(rowsData)
        sources.value = sourcesData
      } else {
        skipNextApiSync = true
        tableState.setRows([])
        sources.value = []
      }
    } catch (error) {
      console.warn('[identifiers] API no disponible, manteniendo estado local en memoria:', error)
      apiReady.value = false
    } finally {
      apiLoading.value = false
    }
  }

  async function syncIdentifiersToApi() {
    if (!apiReady.value) return
    apiSyncing.value = true
    try {
      const res = await apiFetch('/identificadores/bulk_replace/', {
        method: 'POST',
        body: JSON.stringify({
          rows: tableState.rows.value,
          sources: sources.value,
        }),
      })
      if (!res.ok) throw new Error('No se pudieron guardar los identificadores.')
    } catch (error) {
      console.warn('[identifiers] No se pudo sincronizar con API:', error)
    } finally {
      apiSyncing.value = false
    }
  }

  watchDebounced(
    [tableState.rows, sources],
    () => {
      if (skipNextApiSync) {
        skipNextApiSync = false
        return
      }
      syncIdentifiersToApi()
    },
    { debounce: 800, deep: true },
  )

  /**
   * Lee archivos de identificadores
   */
  async function readIdentifierFiles(files) {
    tableState.importError.value = ''
    const aggregatedRows = []
    const aggregatedErrors = []

    for (const file of files) {
      const sourceId = generateId()
      try {
        const text = await file.text()
        const sanitizedText = text.split('\u001a').join('')
        const lines = sanitizedText.split(/\r?\n/)
        const parsedRows = []
        const fileErrors = []

        lines.forEach((line, index) => {
          const result = parseIdentifierLine(line, index + 1, effectiveFormatConfig())
          if (!result) return
          if (result.error) {
            fileErrors.push(`${file.name}: ${result.error}`)
          } else {
            parsedRows.push({
              ...result.row,
              sourceId,
            })
          }
        })

        if (parsedRows.length) {
          aggregatedRows.push(...parsedRows)
        }

        if (fileErrors.length) {
          aggregatedErrors.push(...fileErrors)
        } else if (!parsedRows.length) {
          aggregatedErrors.push(`${file.name}: no se encontraron registros válidos.`)
        }

        const contentLines = lines.filter((line) => line.trim().length > 0).length
        sources.value = [
          ...sources.value,
          {
            id: sourceId,
            name: file.name,
            timestamp: new Date().toISOString(),
            totalLines: contentLines,
            validRows: parsedRows.length,
            errorCount: fileErrors.length,
          },
        ]
      } catch (error) {
        console.error(error)
        aggregatedErrors.push(`${file.name}: error al leer el archivo.`)
      }
    }

    if (aggregatedRows.length) {
      tableState.rows.value = [...tableState.rows.value, ...aggregatedRows]
      tableState.clearSelection()
      tableState.clearEditing()
    }

    if (aggregatedErrors.length) {
      const preview = aggregatedErrors.slice(0, 3).join(' | ')
      tableState.importError.value =
        aggregatedErrors.length > 3 ? `${preview} ...` : preview
    } else if (aggregatedRows.length === 0) {
      tableState.importError.value = 'No se encontraron registros en los archivos seleccionados.'
    } else {
      tableState.importError.value = ''
    }
  }

  /**
   * Handler para drop de archivos
   */
  async function onIdentifierDrop(event) {
    event.preventDefault()
    tableState.isDragging.value = false
    const files = Array.from(event.dataTransfer?.files || [])
    if (!files.length) return
    await readIdentifierFiles(files)
  }

  /**
   * Handler para cambio de archivo
   */
  async function onIdentifierFileChange(event) {
    const files = Array.from(event.target.files || [])
    if (!files.length) return
    await readIdentifierFiles(files)
    event.target.value = ''
  }

  /**
   * Elimina un source y sus filas asociadas
   */
  function removeIdentifierSource(sourceId) {
    tableState.rows.value = tableState.rows.value.filter((row) => row.sourceId !== sourceId)
    sources.value = sources.value.filter((source) => source.id !== sourceId)
    tableState.clearSelection()
    tableState.clearEditing()
  }

  /**
   * Limpia todo incluyendo sources
   */
  function clearAllIdentifiers() {
    tableState.rows.value = []
    sources.value = []
    tableState.clearSelection()
    tableState.clearEditing()
  }

  /**
   * Exporta identificadores a Excel
   */
  async function exportIdentifiersToExcel() {
    if (!tableState.rows.value.length) return
    const { ExcelJS, saveAs } = await loadExcelExportDeps()
    const workbook = new ExcelJS.Workbook()
    const worksheet = workbook.addWorksheet('Identificadores')
    worksheet.columns = [
      { header: 'N° lectura', key: 'lectura' },
      { header: 'DNI', key: 'dni' },
      { header: 'Aula', key: 'aula' },
      { header: 'Tipo', key: 'tipo' },
      { header: 'Litho', key: 'litho' },
      { header: 'Indicador', key: 'indicator' },
      { header: 'Observaciones', key: 'observaciones' },
    ]

    tableState.rows.value.forEach(({ id, rawLine, header, examCode, folio, answers, sourceId, ...rest }) => {
      worksheet.addRow(rest)
    })

    const buffer = await workbook.xlsx.writeBuffer()
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    })
    saveAs(blob, 'identificadores.xlsx')
  }

  async function exportIdentifierObservationsToExcel() {
    const rows = observations.value
    if (!rows.length) return
    const { ExcelJS, saveAs } = await loadExcelExportDeps()
    const workbook = new ExcelJS.Workbook()
    const worksheet = workbook.addWorksheet('Observados')
    worksheet.columns = [
      { header: 'N° lectura', key: 'lectura', width: 14 },
      { header: 'DNI', key: 'dni', width: 12 },
      { header: 'Aula', key: 'aula', width: 10 },
      { header: 'Tipo', key: 'tipo', width: 8 },
      { header: 'Litho', key: 'litho', width: 12 },
      { header: 'Observaciones', key: 'observaciones', width: 60 },
    ]
    worksheet.getRow(1).eachCell((cell) => {
      cell.font = { bold: true, color: { argb: 'FFFFFFFF' } }
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF7C2D12' } }
      cell.alignment = { horizontal: 'center' }
    })
    rows.forEach(({ id, rawLine, header, examCode, folio, answers, sourceId, ...rest }) => {
      worksheet.addRow(rest)
    })
    const buffer = await workbook.xlsx.writeBuffer()
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    })
    saveAs(blob, `observados-identificadores-${new Date().toISOString().slice(0, 10)}.xlsx`)
  }

  /**
   * Exporta observaciones a PDF
   */
  async function exportObservationsPdf() {
    const rows = observations.value
    const { jsPDF, autoTable } = await loadPdfExportDeps()
    const doc = new jsPDF()
    doc.setFontSize(16)
    doc.text('Reporte de observaciones', 14, 18)

    if (rows.length === 0) {
      doc.setFontSize(12)
      doc.text('No se registraron observaciones en los registros cargados.', 14, 28)
    } else {
      const tableBody = rows.map((row, index) => [
        index + 1,
        row.dni || '-',
        row.lectura || '-',
        row.aula || '-',
        row.observaciones,
      ])
      autoTable(doc, {
        startY: 24,
        head: [['#', 'DNI', 'N° lectura', 'Aula', 'Observaciones']],
        body: tableBody,
        styles: {
          fontSize: 10,
          cellPadding: 3,
        },
        headStyles: {
          fillColor: [29, 78, 216],
          textColor: [255, 255, 255],
        },
      })
    }

    doc.save('observaciones.pdf')
  }

  return {
    // Estado de tabla
    ...tableState,

    // Estado específico
    sources,
    apiLoading,
    apiSyncing,
    apiReady,
    identifierHasData,
    observations,
    observationCount,
    observationSummary,
    observationByRowId,
    identifierLookup,
    identifierLookupByLitho,

    // Métodos específicos
    initializeIdentifiers,
    syncIdentifiersToApi,
    readIdentifierFiles,
    onIdentifierDrop,
    onIdentifierFileChange,
    removeIdentifierSource,
    clearAllIdentifiers,
    exportIdentifiersToExcel,
    exportIdentifierObservationsToExcel,
    exportObservationsPdf,
  }
}

import { computed, ref } from 'vue'
import { watchDebounced } from '@vueuse/core'
import { useTableState } from './useTableState'
import { DEFAULT_DAT_FORMAT } from '@/constants'
import { generateId, normalize, stripDigits, buildResponseMatchKey } from '@/utils/helpers'
import { loadExcelExportDeps, loadPdfExportDeps } from '@/utils/exportLoaders'
import {
  createResponseRow,
  buildResponseObservation,
  parseResponseLine,
  parseLinkedResponseLine,
  detectResponseAnswersOffset,
} from '@/utils/parsers'
import { apiFetch } from '@/utils/apiFetch'

export { createResponseRow, buildResponseObservation }

function summarizeObservations(rows) {
  const summary = new Map()
  const add = (label) => summary.set(label, (summary.get(label) || 0) + 1)
  let assumedFinalBlankRows = 0
  let assumedFinalBlankTotal = 0

  rows.forEach((row) => {
    const issues = String(row.observaciones || '')
      .split(' · ')
      .map(issue => issue.trim())
      .filter(Boolean)

    const hasUnlinkedDni = issues.includes('DNI no vinculado')
    const hasUnlinkedTipo = issues.includes('Tipo no vinculado')
    if (hasUnlinkedDni && hasUnlinkedTipo) {
      add('Sin vinculación completa')
    }

    issues.forEach((issue) => {
      const assumedBlanks = issue.match(/^Blancos finales asumidos \((\d+)\)$/)
      if (assumedBlanks) {
        assumedFinalBlankRows += 1
        assumedFinalBlankTotal += Number(assumedBlanks[1]) || 0
        return
      }
      if (hasUnlinkedDni && hasUnlinkedTipo && (issue === 'DNI no vinculado' || issue === 'Tipo no vinculado')) {
        return
      }
      if (/^DNI incompleto \(/.test(issue)) {
        add('DNI incompleto')
        return
      }
      if (/^Litho incompleto \(/.test(issue)) {
        add('Litho incompleto')
        return
      }
      add(issue)
    })
  })

  if (assumedFinalBlankRows) {
    summary.set(
      `Blancos finales asumidos (${assumedFinalBlankTotal} posiciones)`,
      assumedFinalBlankRows
    )
  }
  return Array.from(summary.entries()).map(([label, count]) => ({
    label,
    count,
    informational: isInformationalObservation(label),
  }))
    .sort((a, b) => {
      const priority = [
        'Sin vinculación completa',
        'DNI no vinculado',
        'DNI incompleto',
        'Tipo no vinculado',
        'Litho sin marcar',
        'Litho incompleto',
        'Sin respuestas marcadas',
        'Respuestas con marcas no válidas',
      ]
      if (a.informational !== b.informational) return a.informational ? 1 : -1
      const left = priority.indexOf(a.label)
      const right = priority.indexOf(b.label)
      if (left !== -1 || right !== -1) {
        return (left === -1 ? priority.length : left) - (right === -1 ? priority.length : right)
      }
      return b.count - a.count || a.label.localeCompare(b.label)
    })
}

function splitObservationIssues(row) {
  return String(row.observaciones || '')
    .split(' · ')
    .map(issue => issue.trim())
    .filter(issue => issue && issue !== 'Sin observaciones')
}

function isInformationalObservation(issue) {
  return /^Blancos finales asumidos(?: \(\d+(?: posiciones)?\))?$/.test(String(issue || ''))
}

function hasActionableObservation(row) {
  const issues = splitObservationIssues(row)
  return issues.some(issue => !isInformationalObservation(issue))
}

/**
 * Composable para gestión de respuestas
 */
export function useResponses(identifierLookup, identifierLookupByLitho, formatConfig) {
  const effectiveFormatConfig = () => formatConfig?.value || DEFAULT_DAT_FORMAT
  const tableState = useTableState({
    pageSize: 10,
    createRow: createResponseRow,
    filterFn: (row, searchValue) => {
      const needle = normalize(searchValue)
      return (
        normalize(row.dni).includes(needle) ||
        normalize(row.lectura).includes(needle) ||
        normalize(row.litho).includes(needle) ||
        normalize(row.tipo).includes(needle) ||
        normalize(row.answers).includes(needle) ||
        normalize(row.observaciones).includes(needle)
      )
    },
  })

  // Sources (archivos importados)
  const sources = ref([])
  const apiLoading = ref(false)
  const apiSyncing = ref(false)
  const apiReady = ref(false)
  let skipNextApiSync = false

  // Detección de offset de respuestas
  const detectedOffset = ref(null)
  const configuredResponseAnswersOffset = computed(() =>
    effectiveFormatConfig().responseAnswersOffset ?? DEFAULT_DAT_FORMAT.responseAnswersOffset
  )
  const expectedAnswersLength = computed(() =>
    effectiveFormatConfig().answersLength ?? DEFAULT_DAT_FORMAT.answersLength
  )

  async function detectFormat(file) {
    detectedOffset.value = null
    try {
      const text = await file.text()
      const sanitized = text.split('\u001a').join('')
      const lines = sanitized.split(/\r?\n/).filter(Boolean)
      const result = detectResponseAnswersOffset(lines, effectiveFormatConfig())
      detectedOffset.value = result
    } catch {
      detectedOffset.value = { offset: -1, score: 0, answerPct: 0, digitPct: 1 }
    }
  }

  // Computed
  const responsesHasData = computed(() => tableState.rows.value.length > 0)
  const sourcesCount = computed(() => sources.value.length)

  const observations = computed(() =>
    tableState.rows.value.filter(
      (row) => row.observaciones && row.observaciones !== 'Sin observaciones'
    )
  )

  const observationCount = computed(() => observations.value.length)
  const actionableObservations = computed(() =>
    tableState.rows.value.filter(hasActionableObservation)
  )
  const actionableObservationCount = computed(() => actionableObservations.value.length)
  const observationSummary = computed(() => summarizeObservations(observations.value))
  const observationByRowId = computed(() => {
    const map = new Map()
    actionableObservations.value.forEach(row => map.set(row.id, row))
    return map
  })

  // Lookup por DNI
  const responsesByDni = computed(() => {
    const map = new Map()
    tableState.rows.value.forEach((row) => {
      const dni = stripDigits(row.dni)
      if (!dni) return
      if (!map.has(dni)) {
        map.set(dni, [])
      }
      map.get(dni).push(row)
    })
    return map
  })

  async function initializeResponses() {
    apiLoading.value = true
    try {
      const [rowsRes, sourcesRes] = await Promise.all([
        apiFetch('/respuestas/'),
        apiFetch('/response-sources/'),
      ])
      if (!rowsRes.ok || !sourcesRes.ok) throw new Error('No se pudieron cargar las respuestas.')

      const [rowsData, sourcesData] = await Promise.all([
        rowsRes.json(),
        sourcesRes.json(),
      ])

      apiReady.value = true
      if (rowsData.length > 0 || sourcesData.length > 0) {
        skipNextApiSync = true
        tableState.setRows(rowsData)
        sources.value = sourcesData
      } else {
        skipNextApiSync = true
        tableState.setRows([])
        sources.value = []
      }
    } catch (error) {
      console.warn('[responses] API no disponible, manteniendo estado local en memoria:', error)
      apiReady.value = false
    } finally {
      apiLoading.value = false
    }
  }

  async function syncResponsesToApi() {
    if (!apiReady.value) return
    apiSyncing.value = true
    try {
      const res = await apiFetch('/respuestas/bulk_replace/', {
        method: 'POST',
        body: JSON.stringify({
          rows: tableState.rows.value,
          sources: sources.value,
        }),
      })
      if (!res.ok) throw new Error('No se pudieron guardar las respuestas.')
    } catch (error) {
      console.warn('[responses] No se pudo sincronizar con API:', error)
    } finally {
      apiSyncing.value = false
    }
  }

  watchDebounced(
    [tableState.rows, sources],
    () => {
      if (skipNextApiSync) {
        skipNextApiSync = false
        return
      }
      syncResponsesToApi()
    },
    { debounce: 800, deep: true },
  )

  /**
   * Aplica datos de identificador a una fila de respuesta
   */
  function applyIdentifierDataToResponseRow(row, lookup = identifierLookup?.value, lithoLookup = identifierLookupByLitho?.value) {
    const key = buildResponseMatchKey(row)
    let match = key && lookup ? lookup.get(key) : undefined
    let ambiguousLitho = false
    if (!match && lithoLookup) {
      const litho = stripDigits(row.litho)
      if (lithoLookup.has(litho)) {
        const fallback = lithoLookup.get(litho)
        ambiguousLitho = fallback === null
        match = fallback || undefined
      }
    }

    if (match) {
      row.dni = match.dni
      row.tipo = match.tipo
      row.aula = match.aula || ''
    } else {
      row.dni = row.dni ? stripDigits(row.dni) : ''
      row.tipo = (row.tipo || '').trim().toUpperCase().slice(0, 1)
    }

    const baseObs = buildResponseObservation(row, effectiveFormatConfig())
    const obs = ambiguousLitho
      ? (baseObs === 'Sin observaciones'
        ? 'Litho ambiguo en identificadores'
        : `${baseObs} · Litho ambiguo en identificadores`)
      : baseObs
    if (row.observaciones !== obs) {
      row.observaciones = obs
    }
  }

  /**
   * Lee archivos de respuestas
   */
  async function readResponseFiles(files) {
    tableState.importError.value = ''
    const aggregatedRows = []
    const aggregatedErrors = []

    for (const file of files) {
      const sourceId = generateId()
      try {
        const text = await file.text()
        const sanitizedText = text.split('\u001a').join('')
        const lines = sanitizedText.split(/\r?\n/)
        const parsedRows = []
        const fileErrors = []

        lines.forEach((line, index) => {
          const preliminary = parseResponseLine(line, index + 1, effectiveFormatConfig())
          let linkedIdentifier = null
          if (preliminary?.row) {
            const exactKey = buildResponseMatchKey(preliminary.row)
            linkedIdentifier = identifierLookup?.value?.get(exactKey) || null
            if (!linkedIdentifier) {
              const litho = stripDigits(preliminary.row.litho)
              const fallback = identifierLookupByLitho?.value?.get(litho)
              linkedIdentifier = fallback || null
            }
          }

          const result = linkedIdentifier
            ? parseLinkedResponseLine(line, index + 1, effectiveFormatConfig(), linkedIdentifier)
            : preliminary
          if (!result) return
          if (result.error) {
            fileErrors.push(`${file.name}: ${result.error}`)
          } else {
            applyIdentifierDataToResponseRow(
              result.row,
              identifierLookup?.value,
              identifierLookupByLitho?.value
            )
            parsedRows.push({
              ...result.row,
              sourceId,
            })
          }
        })

        if (parsedRows.length) {
          aggregatedRows.push(...parsedRows)
        }

        if (fileErrors.length) {
          aggregatedErrors.push(...fileErrors)
        } else if (!parsedRows.length) {
          aggregatedErrors.push(`${file.name}: no se encontraron registros válidos.`)
        }

        const contentLines = lines.filter((line) => line.trim().length > 0).length
        sources.value = [
          ...sources.value,
          {
            id: sourceId,
            name: file.name,
            timestamp: new Date().toISOString(),
            totalLines: contentLines,
            validRows: parsedRows.length,
            errorCount: fileErrors.length,
          },
        ]
      } catch (error) {
        console.error(error)
        aggregatedErrors.push(`${file.name}: error al leer el archivo.`)
      }
    }

    if (aggregatedRows.length) {
      tableState.rows.value = [...tableState.rows.value, ...aggregatedRows]
      tableState.clearSelection()
      tableState.clearEditing()
    }

    if (aggregatedErrors.length) {
      const preview = aggregatedErrors.slice(0, 3).join(' | ')
      tableState.importError.value =
        aggregatedErrors.length > 3 ? `${preview} ...` : preview
    } else if (aggregatedRows.length === 0) {
      tableState.importError.value = 'No se encontraron registros en los archivos seleccionados.'
    } else {
      tableState.importError.value = ''
    }
  }

  /**
   * Handler para drop de archivos
   */
  async function onResponseDrop(event) {
    event.preventDefault()
    tableState.isDragging.value = false
    const files = Array.from(event.dataTransfer?.files || [])
    if (!files.length) return
    await readResponseFiles(files)
  }

  /**
   * Handler para cambio de archivo
   */
  async function onResponseFileChange(event) {
    const files = Array.from(event.target.files || [])
    if (!files.length) return
    await readResponseFiles(files)
    event.target.value = ''
  }

  /**
   * Elimina un source y sus filas asociadas
   */
  function removeResponsesSource(sourceId) {
    tableState.rows.value = tableState.rows.value.filter((row) => row.sourceId !== sourceId)
    sources.value = sources.value.filter((source) => source.id !== sourceId)
    tableState.clearSelection()
    tableState.clearEditing()
  }

  /**
   * Limpia todo incluyendo sources
   */
  function clearAllResponses() {
    tableState.rows.value = []
    sources.value = []
    tableState.clearSelection()
    tableState.clearEditing()
  }

  /**
   * Exporta respuestas a Excel
   */
  async function exportResponsesToExcel() {
    if (!tableState.rows.value.length) return
    const { ExcelJS, saveAs } = await loadExcelExportDeps()
    const workbook = new ExcelJS.Workbook()
    const worksheet = workbook.addWorksheet('Respuestas')
    worksheet.columns = [
      { header: 'N° lectura', key: 'lectura' },
      { header: 'DNI', key: 'dni' },
      { header: 'Tipo', key: 'tipo' },
      { header: 'Litho', key: 'litho' },
      { header: 'Respuestas', key: 'answers' },
      { header: 'Observaciones', key: 'observaciones' },
    ]

    tableState.rows.value.forEach(({ id, sourceId, header, examCode, folio, indicator, ...rest }) => {
      worksheet.addRow(rest)
    })

    const buffer = await workbook.xlsx.writeBuffer()
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    })
    saveAs(blob, 'respuestas.xlsx')
  }

  async function exportResponseObservationsToExcel() {
    const rows = actionableObservations.value
    if (!rows.length) return
    const { ExcelJS, saveAs } = await loadExcelExportDeps()
    const workbook = new ExcelJS.Workbook()
    const worksheet = workbook.addWorksheet('Observados')
    worksheet.columns = [
      { header: 'N° lectura', key: 'lectura', width: 14 },
